def grade(score):
    if score >= 90:
        return "A"
    if score >= 70:
        return "B"
    return "C"

print(grade(95), grade(70), grade(10))

def connect(host, port=80):
    return f"{host}:{port}"

print(connect(port=8080))

def first_even(nums):
    for n in nums:
        if n % 2 == 0:
            return n
    return

print(first_even([3, 8]), first_even([1]))
